const trig = $('Store Settings').first().json;
const raw = $('Fetch NBP Rates').first().json;
const tbl = Array.isArray(raw) ? raw[0] : raw;
const eurRow = tbl && Array.isArray(tbl.rates) ? tbl.rates.find(r => r.code === 'EUR') : null;
const eur = eurRow && typeof eurRow.mid === 'number' && eurRow.mid > 0 ? eurRow.mid : null;
const rateDate = eur ? tbl.effectiveDate : null;

const txt = (a) => (a || []).map(t => t.plain_text).join('');
const sel = (p) => (p && p.select ? p.select.name : null);
const num = (p) => (p && typeof p.number === 'number' ? p.number : null);
const fnum = (p) => (p && p.formula && typeof p.formula.number === 'number' ? p.formula.number : null);
const pagesOf = (n) => $(n).all().map(i => i.json).filter(p => p && p.properties);
const r2 = (n) => Math.round(n * 100) / 100;
const pln = (n) => (n == null ? 'N/A' : r2(n) + ' PLN');
const both = (n) => (n == null ? 'N/A' : pln(n) + (eur ? ' (' + r2(n / eur) + ' EUR)' : ''));
// EUR next to PLN: spent in EUR is the sum of each expense's own EUR amount (Spent (EUR) rollup) when the column exists, else today's rate
const pair = (p, e) => (p == null ? 'N/A' : pln(p) + (e != null ? ' (' + r2(e) + ' EUR)' : (eur ? ' (' + r2(p / eur) + ' EUR)' : '')));
const eurOf = (l) => {
  const b = l.budgetEur != null ? l.budgetEur : (eur && l.budget != null ? l.budget / eur : null);
  const s = l.spentEur != null ? l.spentEur : (eur ? l.spent / eur : null);
  return { budget: b, spent: s, left: b != null && s != null ? b - s : null, proj: s != null && day > 0 ? s / day * dim : null };
};
const setIn = (l) => (l.budgetEur != null ? ' [set in EUR: ' + l.budgetEur + ' EUR; its PLN is at the current rate]' : '');

const monthKey = $now.toFormat('yyyy-LL');
const today = $now.toFormat('yyyy-LL-dd');
const day = $now.day, dim = $now.daysInMonth;

const cats = {};
for (const pg of pagesOf('Fetch Budget Categories')) {
  const p = pg.properties;
  cats[pg.id] = { id: pg.id, name: txt(p['Name'] && p['Name'].title), group: sel(p['Group']), type: sel(p['Budget Type']), def: num(p['Default Monthly Budget (PLN)']) };
}
const lines = pagesOf('Fetch Budget Lines').map(pg => {
  const p = pg.properties;
  const rel = p['Category'] && p['Category'].relation && p['Category'].relation[0] ? p['Category'].relation[0].id : null;
  const spent = p['Spent (PLN)'] && p['Spent (PLN)'].rollup && typeof p['Spent (PLN)'].rollup.number === 'number' ? p['Spent (PLN)'].rollup.number : 0;
  const spentEur = p['Spent (EUR)'] && p['Spent (EUR)'].rollup && typeof p['Spent (EUR)'].rollup.number === 'number' ? p['Spent (EUR)'].rollup.number : null;
  // A budget given in euros stays in euros: its PLN value is recalculated at the current rate on every run
  const budgetEur = num(p['Budget (EUR)']) > 0 ? num(p['Budget (EUR)']) : null;
  const budget = budgetEur != null && eur ? r2(budgetEur * eur) : num(p['Budget (PLN)']);
  return {
    id: pg.id, name: txt(p['Name'] && p['Name'].title),
    month: p['Month'] && p['Month'].date ? p['Month'].date.start.slice(0, 7) : null,
    catId: rel, cat: rel && cats[rel] ? cats[rel].name : 'Overall',
    budget, budgetEur, spent, spentEur, left: budget == null ? null : budget - spent, pct: budget > 0 ? Math.round(spent / budget * 100) : null
  };
});
const lineById = Object.fromEntries(lines.map(l => [l.id, l]));
const cur = lines.filter(l => l.month === monthKey);
// Two lines for the same category (or two Overall lines) split the month's spending: keep the fuller one and flag the rest
const overall = cur.filter(l => !l.catId).sort((a, b) => b.spent - a.spent)[0];
const catLines = cur.filter(l => l.catId);
const dupes = Object.values(cur.reduce((g, l) => { const k = l.catId || 'overall'; (g[k] = g[k] || []).push(l); return g; }, {})).filter(g => g.length > 1).map(g => g.sort((a, b) => b.spent - a.spent));

const exps = pagesOf('Fetch Recent Expenses').map(pg => {
  const p = pg.properties;
  const rel = (p['Budget Line'] && p['Budget Line'].relation) || [];
  const cl = rel.map(r => lineById[r.id]).find(l => l && l.catId);
  return {
    id: pg.id, desc: txt(p['Description'] && p['Description'].title),
    date: p['Date'] && p['Date'].date ? p['Date'].date.start.slice(0, 10) : null,
    pln: fnum(p['Amount PLN']), amount: num(p['Amount']), cur: sel(p['Currency']),
    sub: txt(p['Subcategory'] && p['Subcategory'].rich_text) || '-',
    cat: cl ? cl.cat : 'Uncategorised', paidBy: sel(p['Paid By']), card: sel(p['Card Used'])
  };
}).filter(e => e.date).sort((a, b) => (a.date < b.date ? 1 : -1));

// Long-term memory from Notion, read on every message (the agent's own page and the shared page): what they asked to remember
const memText = (n) => { try { const j = $(n).first().json; return typeof j.markdown === 'string' ? j.markdown.split('\n').filter((l) => !l.startsWith('>')).join('\n').trim() : null; } catch (e) { return null; } };
const ownMem = memText('Fetch Agent Memory'), sharedMem = memText('Fetch Shared Memory');
const memFailed = [ownMem === null ? 'your memory page' : '', sharedMem === null ? 'the shared memory page' : ''].filter(Boolean);
const memory = 'WHAT YOU KNOW ABOUT ALEX AND SAM (your Notion memory, read just now: apply every line)\n' + (memFailed.length ? 'MEMORY READ FAILED for ' + memFailed.join(' and ') + ': call Recall Memory once.\n' : '') + '# Shared page (all agents)\n' + (sharedMem || '-') + '\n# Your page\n' + (ownMem || '-');
const out = [memory, ''];
out.push('Read from Notion just now (' + $now.toFormat('yyyy-LL-dd HH:mm') + ' Europe/Rome). Month ' + monthKey + ', day ' + day + ' of ' + dim + ' (' + (dim - day) + ' days left). Talking to: ' + trig.paid_by + '.');
out.push(eur ? 'EXCHANGE RATE: 1 EUR = ' + eur + ' PLN (NBP table A, ' + rateDate + '). Copy it into every expense row as "EUR/PLN Rate" (PLN rows too).' : 'EXCHANGE RATE: LOOKUP FAILED. Do not log any expense in EUR now (tell the user); PLN expenses can still be logged.');

out.push('NBP RATES (PLN per 1 unit' + (tbl && tbl.effectiveDate ? ', ' + tbl.effectiveDate : '') + '): ' + ['EUR', 'USD', 'GBP', 'CHF'].map(c => { const r = tbl && Array.isArray(tbl.rates) ? tbl.rates.find(x => x.code === c) : null; return c + ' ' + (r && typeof r.mid === 'number' ? r.mid : 'N/A'); }).join(', ') + '. Used for subscriptions only.');

const hasBudgets = catLines.some(l => l.budget != null) || (overall && overall.budget != null);
if (!hasBudgets) out.push('SETUP NEEDED: no budget is set for this month yet. Run the setup mode.');

out.push('\nTHIS MONTH, BUDGET LINES (use these ids):');
const room = (l) => {
  if (!(l.budget > 0)) return '';
  const e = eurOf(l);
  const f = (v, ev) => (v <= 0 ? 'already past' : pair(v, ev));
  return ' | room to 80%: ' + f(l.budget * 0.8 - l.spent, e.budget != null && e.spent != null ? e.budget * 0.8 - e.spent : null) + ' | room to 100%: ' + f(l.budget - l.spent, e.left);
};
for (const l of catLines.sort((a, b) => a.cat.localeCompare(b.cat))) {
  const proj = l.budget != null && day > 0 ? r2(l.spent / day * dim) : null;
  const e = eurOf(l);
  out.push('- line ' + l.id + ' | ' + l.cat + ' | budget ' + pair(l.budget, e.budget) + setIn(l) + ' | spent ' + pair(l.spent, e.spent) + ' | left ' + pair(l.left, e.left) + ' | used ' + (l.pct == null ? 'N/A' : l.pct + '%') + room(l) + (proj != null ? ' | projected month-end ' + pair(proj, e.proj) : ''));
}
if (overall) {
  const proj = overall.budget != null ? r2(overall.spent / day * dim) : null;
  const e = eurOf(overall);
  out.push('OVERALL (monthly cap): line ' + overall.id + ' | cap ' + pair(overall.budget, e.budget) + setIn(overall) + ' | spent ' + pair(overall.spent, e.spent) + ' | left ' + pair(overall.left, e.left) + ' | used ' + (overall.pct == null ? 'N/A' : overall.pct + '%') + room(overall) + (proj != null ? ' | projected month-end ' + pair(proj, e.proj) : ''));
} else {
  out.push('OVERALL (monthly cap): NO Overall line exists for this month. Create it with Notion MCP Create Pages (name "Overall – ' + monthKey + '", no category).');
}
if (dupes.length) out.push('DUPLICATE BUDGET LINES THIS MONTH (spending is split between them, so these totals are wrong): ' + dupes.map(g => g[0].cat + ': ' + g.map(l => 'line ' + l.id + ' budget ' + pln(l.budget) + ' spent ' + pln(l.spent)).join(' / ')).join(' ; ') + '. Start your reply with one line telling the user, link new expenses to the first line of each group, never create another line for it.');
const missing = Object.values(cats).filter(c => c.def != null && !catLines.some(l => l.catId === c.id));
if (missing.length) out.push('CATEGORIES WITH A DEFAULT BUDGET BUT NO LINE THIS MONTH (create with Notion MCP Create Pages when needed): ' + missing.map(c => c.name + ' (category id ' + c.id + ', default ' + pln(c.def) + ')').join('; '));

out.push('\nCATEGORIES (ids for new Budget Lines / Related Category): ' + Object.values(cats).sort((a, b) => a.name.localeCompare(b.name)).map(c => c.name + ' [' + c.id + '] ' + (c.group || '?') + '/' + (c.type || '?') + ' default ' + pln(c.def)).join(' ; '));

const todays = exps.filter(e => e.date === today);
out.push('\nLOGGED TODAY (' + today + '): ' + (todays.length ? todays.map(e => e.desc + ' ' + e.amount + ' ' + e.cur + ' (' + e.cat + ', by ' + e.paidBy + ')').join(' ; ') : 'nothing yet'));
out.push('LAST 8 EXPENSES (page ids, for corrections): ' + (exps.slice(0, 8).map(e => 'id ' + e.id + ' | ' + e.date + ' | ' + e.desc + ' | ' + e.amount + ' ' + e.cur + ' | ' + e.cat + '/' + e.sub + ' | ' + e.paidBy + ' | ' + e.card).join(' ;; ') || 'none'));

const prevMonths = [...new Set(lines.filter(l => l.month && l.month < monthKey).map(l => l.month))].sort().reverse().slice(0, 3);
out.push('\nPREVIOUS MONTHS, budget vs spent per category (PLN, then EUR):');
if (!prevMonths.length) out.push('- none yet');
for (const m of prevMonths) {
  const ls = lines.filter(l => l.month === m);
  out.push('- ' + m + ': ' + ls.map(l => l.cat + ' ' + (l.budget == null ? 'N/A' : r2(l.budget)) + '/' + r2(l.spent) + (eur ? ' (' + (l.budget == null ? 'N/A' : r2(eurOf(l).budget)) + '/' + r2(eurOf(l).spent) + ' EUR)' : '')).join(', '));
}

const subTotals = {};
for (const e of exps) {
  const m = e.date.slice(0, 7);
  const k = e.cat + ' > ' + e.sub;
  subTotals[m] = subTotals[m] || {};
  subTotals[m][k] = (subTotals[m][k] || 0) + (e.pln || 0);
}
out.push('\nSPENDING BY SUBCATEGORY, last months (PLN, top 12 each):');
for (const m of Object.keys(subTotals).sort().reverse()) {
  const top = Object.entries(subTotals[m]).sort((a, b) => b[1] - a[1]).slice(0, 12);
  out.push('- ' + m + ': ' + top.map(([k, v]) => k + ' ' + r2(v)).join(', '));
}

return [{ json: { chat_id: trig.chat_id, agent_name: trig.agent_name ?? 'budget', chatInput: trig.chatInput, paid_by: trig.paid_by, eurPlnRate: eur, snapshot: out.join('\n') } }];

// Notion writes this turn REALLY made, read from the agent's own tool calls and Notion's answers (never from the reply text).
// A write whose answer carries no saved id is left out: nothing was saved.
// Each line names the row (title from this run's reads or from the write itself) and the fields written, so memory alone shows what changed.
const SOURCES = ["Fetch Budget Lines", "Fetch Recent Expenses", "Fetch Budget Categories"];
const out = $input.first().json;
const trig = $('Execute Workflow Trigger').first().json;
const WRITE = /create|update|add|confirm|mark|delete|trash|archive|log weekly/i;
const ID = /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/g;
const TITLE_KEYS = ['Task Name', 'Subtask Name', 'Description', 'Name', 'Review', 'Title'];
const names = {};
const titleOf = (o) => {
  if (typeof o.name === 'string' && o.name) return o.name;
  if (typeof o.summary === 'string' && o.summary) return o.summary;
  for (const [k, v] of Object.entries(o.properties || {})) {
    if (v && v.type === 'title') return (v.title || []).map(t => t.plain_text).join('');
    if (TITLE_KEYS.includes(k) && typeof v === 'string') return v;
  }
  return null;
};
const collect = (x, depth = 0) => {
  if (depth > 8) return;
  if (typeof x === 'string') { if (!/^\s*[\[{]/.test(x)) return; try { x = JSON.parse(x); } catch (e) { return; } }
  if (Array.isArray(x)) { x.forEach(v => collect(v, depth + 1)); return; }
  if (!x || typeof x !== 'object') return;
  if (typeof x.id === 'string' && !names[x.id]) { const t = titleOf(x); if (t) names[x.id] = t; }
  for (const v of Object.values(x)) if (v && (typeof v === 'object' || typeof v === 'string')) collect(v, depth + 1);
};
for (const n of SOURCES) { try { collect($(n).all().map(i => i.json)); } catch (e) { /* that read did not run */ } }
const steps = out.intermediateSteps || [];
for (const s of steps) collect(s.observation);
const short = (v) => (typeof v === 'string' ? v : JSON.stringify(v)).replace(/\s+/g, ' ').slice(0, 150);
const lines = [];
for (const step of steps) {
  const tool = String((step.action && step.action.tool) || '');
  if (!WRITE.test(tool)) continue;
  const obs = typeof step.observation === 'string' ? step.observation : JSON.stringify(step.observation ?? '');
  // An error answer saved nothing, even though it carries ids (request_id, integration_id, the data_source id)
  if (/APIResponseError|"error"\s*:|object_not_found|validation_error|Could not find|MCP error|timed out/i.test(obs)) continue;
  const ids = [...new Set(obs.match(ID) || [])];
  if (!ids.length || /"properties":\{\}/.test(obs)) continue;
  const inp = (step.action && step.action.toolInput) ?? {};
  const label = (id) => (names[id] ? '"' + names[id] + '" (' + id + ')' : id);
  // ids already in the input are the row being updated or rows the new one links to; the others are the rows just created
  const inInput = JSON.stringify(inp);
  const isCreate = /create|add/i.test(tool);
  const saved = isCreate ? ids.filter(id => !inInput.includes(id)) : ids;
  const linked = isCreate ? ids.filter(id => inInput.includes(id)) : [];
  const fields = (p) => Object.entries(p).map(([k, v]) => k + ' = ' + short(v)).join('; ');
  const props = inp && typeof inp === 'object' && inp.properties && typeof inp.properties === 'object' && !Array.isArray(inp.properties) ? inp.properties : null;
  const pages = inp && typeof inp === 'object' && Array.isArray(inp.pages) ? inp.pages : null;
  const written = props ? fields(props) : pages ? pages.map(p => fields(p.properties || {})).join(' || ') : JSON.stringify(inp).replace(/\s+/g, ' ').slice(0, 700);
  lines.push('- ' + tool + ' -> saved in Notion: ' + (saved.length ? saved : ids).map(label).join(', ') + (linked.length ? ' | linked to: ' + linked.map(label).join(', ') : '') + ' | written: ' + written);
}
const action_log = lines.length
  ? '[ACTION LOG, ' + $now.toFormat('yyyy-LL-dd HH:mm') + ', written by the workflow from the tool results of my previous reply: these Notion writes are DONE. Never make them again.]\n' + lines.join('\n')
  : '';
const { intermediateSteps, ...reply } = out;
// The agent sometimes copies an earlier action log from its chat memory into its reply: never send it
if (typeof reply.output === 'string') reply.output = reply.output.replace(/\s*\[ACTION LOG[^\]\n]*\][^\n]*(\n- [^\n]*)*/g, '').trim();
return [{ json: { ...reply, chat_id: String(trig.chat_id ?? ''), agent_name: trig.agent_name || 'budget', action_log } }];

// What this turn adds to the agent's chat memory (Postgres), saved by Save To Memory:
// the ACTION LOG, i.e. the Notion writes this turn really made (from Build Action Log), as a hidden message,
// stored exactly as the Chat Memory Manager stored it. Nothing to save gives an empty list.
const log = $('Build Action Log').first().json;
const session_id = 'demo-' + log.chat_id + '-' + log.agent_name;
const ai = (content, hidden) => ({ type: 'ai', content, tool_calls: [], additional_kwargs: hidden ? { hideFromUI: true } : {}, response_metadata: {}, invalid_tool_calls: [] });
const writes = log.action_log ? [{ op: 'add', session_id, message: ai(String(log.action_log), true) }] : [];
return [{ json: { writes } }];

// The budget card for Telegram, computed from Notion AFTER this turn's writes (the snapshot was read before them).
// Rows: after an expense write, the category lines it went to; with the reply line "[card: budget]" every category line
// of this month, "[card: budget yyyy-LL]" every line of that month. The overall cap comes last.
// The same rule as the snapshot: a budget set in EUR is converted at today's NBP rate; EUR spent is the sum of each expense's EUR.
const act = $('Build Action Log').first().json;
const reply = String(act.output || '');
const log = String(act.action_log || '');
const eur = $('Build Budget Snapshot').first().json.eurPlnRate;
const lang = 'en';
const txt = (a) => (a || []).map((t) => t.plain_text).join('');
const num = (p) => (p && typeof p.number === 'number' ? p.number : null);
const roll = (p) => (p && p.rollup && typeof p.rollup.number === 'number' ? p.rollup.number : null);
const r2 = (n) => (n == null ? null : Math.round(n * 100) / 100);
const cats = {};
for (const i of $('Fetch Budget Categories').all()) { const pg = i.json; if (pg && pg.properties) cats[pg.id] = txt(pg.properties['Name'] && pg.properties['Name'].title); }
const lines = $('Fetch Budget Lines After Reply').all().map((i) => i.json).filter((pg) => pg && pg.properties).map((pg) => {
  const p = pg.properties;
  const catId = p['Category'] && p['Category'].relation && p['Category'].relation[0] ? p['Category'].relation[0].id : null;
  const budgetEur = num(p['Budget (EUR)']) > 0 ? num(p['Budget (EUR)']) : null;
  const budget = budgetEur != null && eur ? r2(budgetEur * eur) : num(p['Budget (PLN)']);
  const spent = roll(p['Spent (PLN)']) || 0;
  const spentEur = roll(p['Spent (EUR)']);
  const bEur = budgetEur != null ? budgetEur : eur && budget != null ? budget / eur : null;
  const sEur = spentEur != null ? spentEur : eur ? spent / eur : null;
  return { id: pg.id, month: p['Month'] && p['Month'].date ? p['Month'].date.start.slice(0, 7) : null, catId, name: catId ? cats[catId] || txt(p['Name'] && p['Name'].title) : 'Overall', budget, spent: r2(spent), leftEur: bEur != null && sEur != null ? r2(bEur - sEur) : null };
});
const ask = ([...reply.matchAll(/\[card:\s*([^\]\n]*)\]/gi)].pop() || [])[1] || '';
const ids = new Set(log.match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/g) || []);
let month = $now.toFormat('yyyy-LL');
let rows = [];
if (/budget/i.test(ask)) {
  const m = ask.match(/\d{4}-\d{2}/);
  if (m) month = m[0];
  rows = lines.filter((l) => l.month === month && l.catId);
} else {
  rows = lines.filter((l) => ids.has(l.id) && l.catId);
  if (rows.length) month = rows[0].month || month;
}
// Two lines for one category split its spending: show the fuller one, as the snapshot does
const best = {};
for (const l of rows) if (!best[l.catId] || l.spent > best[l.catId].spent) best[l.catId] = l;
rows = Object.values(best).sort((a, b) => a.name.localeCompare(b.name));
const overall = lines.filter((l) => l.month === month && !l.catId).sort((a, b) => b.spent - a.spent)[0] || null;
const title = DateTime.fromISO(month + '-01').setLocale(lang).toFormat('LLLL yyyy') + ' · budget';
return [{ json: { budget: rows.length ? { title, lang, rows, overall } : {} } }];
